import{_ as d,o,c as r,a2 as e}from"./chunks/framework.YT-FC_Xx.js";const p=JSON.parse('{"title":"订阅与客户端","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscription.md","filePath":"guide/subscription.md","lastUpdated":1792750293000}'),a={name:"guide/subscription.md"};function s(i,t,l,n,h,c){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="订阅与客户端" tabindex="-1">订阅与客户端 <a class="header-anchor" href="#订阅与客户端" aria-label="Permalink to &quot;订阅与客户端&quot;">​</a></h1><p><strong>订阅</strong> 页管理所有订阅链接。思路和 Sub-Store 一样：<strong>来源 → 处理 → 输出</strong>。页面上方分成 <strong>订阅</strong> 和 <strong>节点组</strong> 两个标签：</p><ul><li><strong>节点组</strong>：从节点和订阅源里挑选，筛选、改名、排序后存成一份节点列表，见 <a href="./subscription-sources">节点组与订阅源</a></li><li><strong>订阅</strong>：选一个或几个节点组，再加分流规则、链式代理和模板，客户端拿到的格式按 UA 自动识别（也可以复制指定格式的链接）</li></ul><p>同一个节点组可以给多个订阅用，改一次所有订阅都跟着变。</p><p>升级前的订阅链接会变成这里的“我的订阅”，链接不变；原来的订阅设置和共享用户也会自动迁移过来。升级到有节点组的版本时，每个订阅原来的来源、筛选、命名和脚本会搬进一个同名的节点组，订阅输出的节点不变。</p><h2 id="管理订阅" tabindex="-1">管理订阅 <a class="header-anchor" href="#管理订阅" aria-label="Permalink to &quot;管理订阅&quot;">​</a></h2><p>所有订阅在同一个列表里，靠名称区分（例如“我的手机”“小明”）。</p><ul><li>新建的订阅都有自己的凭据，可以设到期和流量上限，适合分给别人，见 <a href="./subscription-users">凭据、到期与流量</a></li><li>可以把订阅分配给面板用户，对方登录面板就能自己导入和查看流量，见 <a href="./subscription-users#分配给面板用户">分配给面板用户</a></li></ul><p>编辑订阅分成 <strong>基本 / 节点 / 规则 / 预览</strong> 四页，在任一页都能直接保存：</p><ul><li><strong>基本</strong>：名称、到期、流量上限、每月重置、备注</li><li><strong>节点</strong>：选用哪些 <a href="./subscription-sources">节点组</a>，按列表顺序输出，可以上下调整</li><li><strong>规则</strong>：<a href="./subscription-rules">分流规则、按地区分组和链式代理</a></li><li><strong>预览</strong>：打开就自动生成，看最终的节点和链式角色</li></ul><p>链式代理默认折叠，标题旁显示当前设置了什么（例如“改名 2 条、国旗”），点开即可修改。</p><p>订阅列表右上角可以在列表和卡片之间切换，选择会记在浏览器里。</p><h2 id="导入到客户端" tabindex="-1">导入到客户端 <a class="header-anchor" href="#导入到客户端" aria-label="Permalink to &quot;导入到客户端&quot;">​</a></h2><p>点订阅打开详情，按客户端选择：<strong>点客户端直接唤起 App 导入</strong>，右侧按钮复制该格式的链接。也可以复制上面的通用链接，客户端按 UA 自动拿到对应格式。</p><table tabindex="0"><thead><tr><th>客户端</th><th>格式</th><th>一键导入</th><th>链式代理</th><th>分流规则</th></tr></thead><tbody><tr><td>mihomo（Clash Verge Rev、Mihomo Party、FlClash 等）</td><td>Clash / Mihomo 配置</td><td><code>clash://</code></td><td>✓</td><td>✓（需 mihomo 内核）</td></tr><tr><td>sing-box（SFA / SFI / SFM）</td><td>sing-box 配置</td><td><code>sing-box://</code></td><td>✓</td><td>✓（需 1.12 及以上）</td></tr><tr><td>Shadowrocket</td><td>Clash 节点列表</td><td><code>shadowrocket://</code></td><td>✓（每个中转各生成一个“落地（经 中转）”节点）</td><td>✓（下发完整配置）</td></tr><tr><td>Loon</td><td>Loon 节点</td><td><code>loon://</code></td><td>✗</td><td>✓（下发完整配置，复制链接导入）</td></tr><tr><td>Quantumult X</td><td>QX 节点</td><td><code>quantumult-x://</code></td><td>✗</td><td>✓（下发完整配置，复制链接导入）</td></tr><tr><td>Surge</td><td>Surge 配置</td><td><code>surge://</code></td><td>✓</td><td>✓</td></tr><tr><td>Stash</td><td>Clash 配置</td><td><code>stash://</code></td><td>✓</td><td>✓（规则集用 YAML 格式）</td></tr><tr><td>通用</td><td>Base64 分享链接（v2rayN、NekoBox 等）</td><td>仅复制</td><td>✗</td><td>✗</td></tr></tbody></table><ul><li>客户端不支持的协议会自动略过（完整列表见下表），例如 Loon 没有 TUIC，Quantumult X 没有 Hysteria2 / TUIC，Surge 没有 VLESS；VLESS Encryption 只在 Clash / Mihomo 和通用订阅里，WireGuard 只在 Clash / Mihomo、sing-box 和通用订阅里</li><li>Loon 和 Quantumult X 的节点格式没有前置代理参数，订阅里的落地节点是直连</li><li>指定格式的链接：在订阅链接后加 <code>?format=clash</code>（或 <code>singbox</code>、<code>shadowrocket</code>、<code>loon</code>、<code>qx</code>、<code>surge</code>、<code>stash</code>、<code>base64</code>）</li></ul><h3 id="各格式不包含的协议" tabindex="-1">各格式不包含的协议 <a class="header-anchor" href="#各格式不包含的协议" aria-label="Permalink to &quot;各格式不包含的协议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>订阅格式</th><th>不包含</th></tr></thead><tbody><tr><td>Clash / Mihomo</td><td>XHTTP、Snell、NaïveProxy</td></tr><tr><td>sing-box</td><td>XHTTP、VLESS Encryption；Snell 只给 1.14 及以上的客户端</td></tr><tr><td>Shadowrocket</td><td>XHTTP、Snell、NaïveProxy、WireGuard、VLESS Encryption</td></tr><tr><td>Loon</td><td>TUIC、gRPC、XHTTP、Snell、NaïveProxy、WireGuard、VLESS Encryption</td></tr><tr><td>Quantumult X</td><td>Hysteria2、TUIC、gRPC、XHTTP、ShadowTLS、Snell、NaïveProxy、WireGuard、VLESS Encryption</td></tr><tr><td>通用 base64</td><td>Snell、HTTP 代理</td></tr><tr><td>Surge</td><td>VLESS、Reality、gRPC、XHTTP、NaïveProxy、WireGuard</td></tr></tbody></table><p>Snell 只在 Surge 和 sing-box 1.14+ 的订阅里，原因见 <a href="./kernels#客户端和出站">Snell 用哪个内核 - 客户端和出站</a>。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><ul><li>点订阅可以导入到客户端、复制各种格式的链接、编辑、重置链接或删除</li><li>所有订阅都包含在 <a href="./backup">备份</a> 的“内核与入站”里</li></ul>',21)])])}const g=d(a,[["render",s]]);export{p as __pageData,g as default};
